def add_conditional_publication_hook(apps, schema_editor):
    transition_model = apps.get_model('tasks', 'WorkflowTransition')
    for transition in transition_model.objects.all().iterator():
        name = (transition.name or '').strip().lower()
        if 'submit for' not in name or 'review' not in name:
            continue
        post_functions = transition.post_functions
        if not isinstance(post_functions, list):
            continue
        if any(isinstance(pf, dict) and pf.get('type') == 'publication_handoff' for pf in post_functions):
            continue
        transition.post_functions = [
            *post_functions,
            {
                'type': 'publication_handoff',
                'required_label': 'publication-binding-required',
            },
        ]
        transition.save(update_fields=['post_functions'])


def remove_conditional_publication_hook(apps, schema_editor):
    transition_model = apps.get_model('tasks', 'WorkflowTransition')
    for transition in transition_model.objects.all().iterator():
        post_functions = transition.post_functions
        if not isinstance(post_functions, list):
            continue
        filtered = [
            pf for pf in post_functions
            if not (
                isinstance(pf, dict)
                and pf.get('type') == 'publication_handoff'
                and pf.get('required_label') == 'publication-binding-required'
            )
        ]
        if filtered != post_functions:
            transition.post_functions = filtered
            transition.save(update_fields=['post_functions'])


